import{_ as o,o as t,c as a,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"一起听音乐管线","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/music-pipeline.md","filePath":"advanced/music-pipeline.md","lastUpdated":1793354072000}'),c={name:"advanced/music-pipeline.md"};function i(s,e,r,n,l,u){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="一起听音乐管线" tabindex="-1">一起听音乐管线 <a class="header-anchor" href="#一起听音乐管线" aria-label="Permalink to &quot;一起听音乐管线&quot;">​</a></h1><p>一起听让房间成员同步播放同一首歌、同一段进度。本页说明服务拓扑、网易云登录态转发、音频流代理的降级与防护、房间同步算法、B站音乐特有逻辑与歌词处理。</p><h2 id="服务拓扑" tabindex="-1">服务拓扑 <a class="header-anchor" href="#服务拓扑" aria-label="Permalink to &quot;服务拓扑&quot;">​</a></h2><p>网易云接口在进程内实现，没有中间服务，也不存在「音乐服务未启动」这种状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前端 &lt;audio&gt;</span></span>\n<span class="line"><span>   │  /api/music/stream?songId=&amp;level=&amp;roomId=</span></span>\n<span class="line"><span>   ▼</span></span>\n<span class="line"><span>后端 /api/music/*   internal/ncm（拼参数、注入凭证、解析音质）</span></span>\n<span class="line"><span>   ▼</span></span>\n<span class="line"><span>网易云上游</span></span></code></pre></div><p>拿不到数据只可能是请求本身失败（风控 / 地区 / 版权），日志前缀 <code>[ncm]</code>。</p><h2 id="路由与登录态-api-music-ncm" tabindex="-1">路由与登录态（<code>/api/music/ncm/*</code>） <a class="header-anchor" href="#路由与登录态-api-music-ncm" aria-label="Permalink to &quot;路由与登录态（`/api/music/ncm/*`）&quot;">​</a></h2><ul><li><strong>通用转发</strong>：只放行 GET / POST。自动注入当前用户持久化的网易云 Cookie（<code>ncm_credential</code> 表按 userId 隔离，游客不落库），并<strong>剥离 query / body 中的 <code>cookie</code> / <code>noCookie</code> 参数</strong>，防止客户端伪造登录态。</li><li><strong>扫码登录</strong>（<code>/login/qr/key|create|check</code>）<strong>不注入旧凭据</strong>：网易云以请求携带的 cookie 判定登录态，带上过期 MUSIC_U 会让二维码轮询异常（800 循环）。check 成功（803）的 Set-Cookie 正常持久化，并解析 profile（昵称 / 头像 / vipType）。</li><li><strong>Cookie 登录</strong>（<code>/api/music/ncm-cookie-login</code>）：个人中心可直接粘贴 Cookie 登录，提交时先校验 MUSIC_U 是否对应有效登录态，再持久化并同步昵称 / 头像缓存；过期或错误返回 400。<code>GET /api/music/ncm-cookie</code> 返回 <code>MUSIC_U=xxx; __csrf=yyy</code> 格式串，供「复制 Cookie」迁移登录态。</li><li>Cookie 持久化判定：Set-Cookie 含 <code>music_u</code>，或名称含 <code>csrf</code>；按 cookie 名去重合并，新值覆盖旧值。</li><li>VIP 归一：<code>/vip/info</code> 兜底后 10 为 VIP、11 为 SVIP；黑胶、音乐包、PLUS 三档会员对象也参与有效期判定。</li><li>上游 3xx 不跟随，改以 <code>{ code: &#39;REDIRECT&#39;, location }</code> 回传前端。</li></ul><h2 id="音频流代理-api-music-stream" tabindex="-1">音频流代理 <code>/api/music/stream</code> <a class="header-anchor" href="#音频流代理-api-music-stream" aria-label="Permalink to &quot;音频流代理 `/api/music/stream`&quot;">​</a></h2><h3 id="音质降级链" tabindex="-1">音质降级链 <a class="header-anchor" href="#音质降级链" aria-label="Permalink to &quot;音质降级链&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lossless → exhigh → higher → standard</span></span></code></pre></div><p>从请求档位（默认 <code>exhigh</code>）在链中的位置开始逐档尝试 <code>/song/url/v1</code>。只有 <code>data.url</code> 非空且 <strong><code>freeTrialInfo == null</code></strong> 才算可用（试听片段视同不可用）。全链失败且过程中出现过试听片段时返回 403 <code>VIP_REQUIRED</code>。</p><h3 id="回退与防护" tabindex="-1">回退与防护 <a class="header-anchor" href="#回退与防护" aria-label="Permalink to &quot;回退与防护&quot;">​</a></h3><ul><li><strong>v1 → 老接口回退</strong>：<code>/song/url/v1</code> 返回 404（内部服务依赖残缺）时回退 <code>/song/url</code>。level→br 映射：lossless 999000 / exhigh 320000 / higher 192000 / standard 128000。</li><li><strong>凭证回退链</strong>：当前用户 Cookie → 房主 Cookie（请求带 <code>roomId</code> 时反查 <code>Room.ownerUserId</code>），房主登录 VIP 后全房间可用。<code>&lt;audio&gt;</code> 无法携带 Authorization 头，token 从 query 读取。</li><li><strong>SSRF 防护</strong>：解析出的直链域名必须匹配 <code>*.music.126.net</code>，否则拒绝转发。</li><li><strong>direct=1 模式</strong>：用 302 把 CDN 直链交给 <code>&lt;audio&gt;</code> 直连，减少服务器带宽。直链缓存 <strong>15 分钟</strong>（签名有效期 20~30 分钟），key 含实际生效凭证的归属，VIP 直链只会发给同一凭证链的请求。<code>http:</code> 直链统一改写为 <code>https:</code>。</li><li>代理流模式透传 Range（上游 206 必须转发），1MB 高水位读块，断连时 abort 上游并销毁流。</li><li>错误码：403 <code>VIP_REQUIRED</code> / 404 <code>NO_COPYRIGHT</code>（<code>/check/music</code> 判定）/ 502 <code>RESOLVE_FAILED</code>。</li></ul><h2 id="房间内同步" tabindex="-1">房间内同步 <a class="header-anchor" href="#房间内同步" aria-label="Permalink to &quot;房间内同步&quot;">​</a></h2><h3 id="队列模型-单表双源-视图过滤" tabindex="-1">队列模型：单表双源 + 视图过滤 <a class="header-anchor" href="#队列模型-单表双源-视图过滤" aria-label="Permalink to &quot;队列模型：单表双源 + 视图过滤&quot;">​</a></h3><p>队列持久化在 <code>MusicQueueItem</code> 单表，用 <code>source</code> 区分 ncm / bili。前端用<strong>视图过滤</strong>实现「双源独立列表」（<code>activeQueueOf</code>）：当前曲目 key 以 <code>bili:</code> 开头时显示 B站列表，否则显示网易云列表；切歌与洗牌都在活动列表内推进。</p><ul><li>权威 key：<code>ncm:&lt;songId&gt;</code> 与 <code>bili:&lt;bvid&gt;:&lt;cid&gt;</code>（BV 号用 <code>^BV[0-9A-Za-z]{10}$</code> 校验）。</li><li><strong>封面防盗链兜底</strong>：hdslb.com 直链在应用内会 403，<code>setQueue</code> 统一入口把 B站封面改写为 <code>/api/stream/proxy-image</code>。新增 B站数据源时不要存原始直链。</li><li>队列操作（upsert / remove / reorder / clear）走 ack + <code>music:queue-changed</code> 完整广播。<code>afterCurrent: true</code> 表示插到当前曲目之后并右移后续 order；删除后 order 压实为 1..n。</li></ul><h3 id="同步事件与进度对齐" tabindex="-1">同步事件与进度对齐 <a class="header-anchor" href="#同步事件与进度对齐" aria-label="Permalink to &quot;同步事件与进度对齐&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>说明</th></tr></thead><tbody><tr><td><code>music:sync-state</code></td><td>房主→全员：<code>{trackSongId, trackKey, isPlaying, positionSec, playMode, updatedAt}</code></td></tr><tr><td><code>music:host-heartbeat</code></td><td>房主每 <strong>2s</strong>；<code>visibilitychange</code> 回前台立即补发</td></tr><tr><td><code>music:control-request</code> / <code>music:control-response</code></td><td>观众申请 <code>pause/play/next/prev/addQueue/seek/playItem</code>；<code>from/username</code> 由服务端 socket 身份注入防伪造；seek 上限 86400s</td></tr><tr><td><code>music:sync-ack</code></td><td>观众切歌同步成功回执（房主「xx 已同步」提示）</td></tr><tr><td><code>music:get-state</code></td><td>进房拉取 <code>{queue, syncState}</code>；失败退避重试 500ms×2（上限 3s）直到入房成功</td></tr></tbody></table><ul><li>观众离线判定：<strong>7s</strong> 未收到心跳（3.5 倍间隔）；页面 hidden 时跳过判定。</li><li>进度对齐：相差 <strong>&gt;2s</strong> 才 seek；延迟补偿为 <code>positionSec + (Date.now()-updatedAt)/1000</code>，上限 <strong>10s</strong>，时钟不同源时回退原值。</li><li><strong>同步状态只存内存 Map</strong>：房主离线即失效，观众随之进入自主控制（<code>canControl = isHost || hostOffline</code>）；队列持久化，房间删除时清内存态。</li><li><code>addQueue</code> 申请不走审批弹窗：房主开启「自动通过」时直接代理入队，否则返回拒绝回执。</li></ul><h2 id="b站音乐特有逻辑" tabindex="-1">B站音乐特有逻辑 <a class="header-anchor" href="#b站音乐特有逻辑" aria-label="Permalink to &quot;B站音乐特有逻辑&quot;">​</a></h2><h3 id="搜索分页-200-虚拟页" tabindex="-1">搜索分页（200 虚拟页） <a class="header-anchor" href="#搜索分页-200-虚拟页" aria-label="Permalink to &quot;搜索分页（200 虚拟页）&quot;">​</a></h3><p>B站单排序最多 50 页、<code>numResults</code> 封顶 1000。后端把 <strong>4 个排序分片</strong>（综合 / 最多点击 / 最多弹幕 / 最多收藏，「最新发布」因时间线跳变不参与）各 50 页合并为 <strong>200 虚拟页</strong>（<code>SEARCH_MAX_PAGES = 200</code>，前后端同值），按 <code>虚拟页 → (order 分片, 真实页码)</code> 线性映射。随机模式从 1..200 抽页，再对当页做 Fisher-Yates 打乱。</p><h3 id="自动连播-biliautocontinue-默认开启" tabindex="-1">自动连播（<code>biliAutoContinue</code>，默认开启） <a class="header-anchor" href="#自动连播-biliautocontinue-默认开启" aria-label="Permalink to &quot;自动连播（`biliAutoContinue`，默认开启）&quot;">​</a></h3><p>只由用户主动点「下一首」触发；自然播完不触发，order 模式到末尾自然停止。链路：<code>/api/stream/bilibili/related</code> 拉推荐 → 去重已有队列 → 取前 3 条 → <strong>倒序逐条以 <code>afterCurrent: true</code> 入队</strong>（最终顺序与推荐一致）→ 标记 <code>recommended: true</code> → 续播第一条。拉取失败则回落为自然停止。</p><h3 id="视频背景解析链-usemusicvideobackground-ts" tabindex="-1">视频背景解析链（<code>useMusicVideoBackground.ts</code>） <a class="header-anchor" href="#视频背景解析链-usemusicvideobackground-ts" aria-label="Permalink to &quot;视频背景解析链（`useMusicVideoBackground.ts`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>前提</th><th>链路</th><th>清晰度</th></tr></thead><tbody><tr><td>CLI 开启且本地代理已连接</td><td>CLI DASH 双轨</td><td>按分辨率选择指定档；<code>qn=0</code> 跟随账号默认（非大会员选了会员档时自动回落）</td></tr><tr><td>CLI 开启但代理未连接</td><td>服务器 MP4 直链（<code>preferMp4</code>，不回退 DASH）</td><td>固定 720P</td></tr><tr><td>CLI 关闭</td><td>由「服务器 DASH 解析模式」决定走服务器 DASH 双轨或 MP4 直链</td><td>DASH 同上；MP4 固定 720P</td></tr></tbody></table><p>分辨率选择（qn）对 CLI DASH 与服务器 DASH 均生效，MP4 直链忽略该设置。B站音频直链缓存 <strong>2 小时</strong>（直链本身 1~4 小时过期）。</p><ul><li><strong>可见性门控</strong>：视频元素要等到 <code>canplay/playing</code>（首帧可播）才淡入，未就绪期间透出封面模糊背景——URL 就绪不等于画面就绪。</li><li><strong>进度同步</strong>：1s interval 命令式驱动。漂移 &gt;1.5s 时先去抖（350ms）再 seek，并进入追赶模式（<code>rate = 1 + drift/4</code>，夹在 0.6~1.5，误差 ≤0.35s 后恢复原速）；<code>readyState &lt; 3</code> 时跳过校正，防止 DASH 连续 seek 造成缓冲风暴。DASH 时长必须显式传给引擎（容器为 mvvh 时读出来是 0，缺失会让进度同步全部失效）。</li></ul><h2 id="歌词" tabindex="-1">歌词 <a class="header-anchor" href="#歌词" aria-label="Permalink to &quot;歌词&quot;">​</a></h2><ul><li>网易云：<code>/api/music/ncm/lyric</code> 做三轨合并（原文 / 翻译 / 音译）；B站：走 AI 字幕接口，必须传 <code>&amp;duration=</code>，带内校验见<a href="/advanced/video-pipeline">视频管线</a>。</li><li>单行偏移：右键菜单提前或延后（步长 0.5s），按 <code>songKey → lineKey</code> 持久化。显示时间 = 原时间 − 偏移，并强制单调递增，防止行序错乱。</li></ul>',32)])])}const g=o(c,[["render",i]]);export{p as __pageData,g as default};
